{
  "name": "pairwise_advantage_cost_gap_loss",
  "intuition": "This loss encourages preference of higher advantage scores while minimizing cost gaps, promoting better decision quality that aligns with the advantage signal. It combines advantage and cost gap signals to guide the model toward preferred pairs, balancing reward and penalty signals for improved ranking.",
  "pseudocode": "loss = mean over pairs of [ -logsigmoid(advantage_w - advantage_l) + lambda * logsigmoid(cost_gap) ]",
  "hyperparams": {
    "paradigm_family": "ranking",
    "signal_family": "advantage_cost",
    "link_family": "sigmoid",
    "agg_family": "pairwise",
    "constraint_family": "cost_constraint",
    "other_hparams": "lambda=1.0"
  },
  "operators_used": ["logsigmoid"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_w", "advantage_l", "cost_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap = batch['cost_gap']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    lambda_ = float(extra.get('lambda', 1.0))\n    pairwise_adv = ops.logsigmoid(ops.sub(advantage_w, advantage_l))\n    pairwise_cost = ops.logsigmoid(ops.neg(cost_gap))\n    loss_per_pair = ops.without_grad(ops.neg(pairwise_adv))\n    combined_loss = ops.add(loss_per_pair, ops.mul(lambda_, ops.neg(pairwise_cost)))\n    weighted_loss = ops.mul(combined_loss, weight)\n    return ops.mean(weighted_loss)"
}

