  "code": "def generated_loss(batch, model_output, extra):\n    advantage_w = batch['advantage_w']\n    advantage_l = batch['advantage_l']\n    cost_gap = batch['cost_gap']\n    log_prob_w = batch['log_prob_w']\n    log_prob_l = batch['log_prob_l']\n    weight = batch['weight']\n    advantage_diff = ops.sub(advantage_w, advantage_l)\n    cost_gap_clamped = ops.clamp(cost_gap, min=0.0)\n    pairwise_score = ops.logsigmoid(advantage_diff)\n    weighted_score = ops.mul(pairwise_score, cost_gap_clamped)\n    loss = ops.mean(weighted_score)\n    return loss"
