  "code": "def generated_loss(batch, model_output, extra):\n    eps = 1e-8\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', lpw.new_ones(lpw.shape))\n    advantage_gap = batch.get('advantage_gap', lpw.new_zeros(lpw.shape))\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    diff = ops.sub(lpw, lpl)\n    scaled_diff = ops.clamp(ops.mul(alpha, diff), -10.0, 10.0)\n    smooth_rank = ops.tanh(scaled_diff)\n    base_loss = ops.mul(ops.sub(ops.ones_like(smooth_rank), smooth_rank), advantage_gap)\n    base_loss = ops.mul(base_loss, weight)\n    return ops.mean(base_loss)\n"
