{
  "name": "pairwise_margin_advantage_tanh",
  "intuition": "This loss emphasizes margin ranking between sequences by considering the difference in log probabilities, scaled by alpha, passed through a tanh to smooth the margin. It is weighted by the advantage gap magnitude, reinforcing higher-advantage pairs, which guides the model to prefer sequences with better advantage scores. Using pairwise differences and a non-linear link ensures the training focuses on relative quality while maintaining stability via the tanh and relu functions.",
  "pseudocode": "margin = log_prob_w - log_prob_l\nscaled_margin = alpha * margin\nsmooth_margin = tanh(scaled_margin)\nweight = abs(advantage_gap)\nloss_per_pair = relu(1 - smooth_margin) * weight * weight\nfinal_loss = mean(loss_per_pair)",
  "hyperparams": {
    "paradigm_family": "pairwise_margin_rank_blend",
    "signal_family": "advantage_gap",
    "link_family": "tanh_relu",
    "agg_family": "mean",
    "constraint_family": "relu_weighted",
    "other_hparams": "optional"
  },
  "operators_used": ["tanh", "relu", "abs", "mul", "sub", "mean"],
  "implementation_hint": {
    "expects": ["log_prob_w", "log_prob_l", "weight", "advantage_gap"],
    "returns": "scalar",
    "mode": "pairwise"
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n    advantage_gap = batch['advantage_gap']\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    margin = ops.sub(lpw, lpl)\n    scaled_margin = ops.mul(alpha, margin)\n    smooth_margin = ops.tanh(scaled_margin)\n    weight_factor = ops.abs(advantage_gap)\n    hinge_loss = ops.relu(ops.sub(ops.ones_like(smooth_margin), smooth_margin))\n    loss = ops.mul(hinge_loss, weight_factor)\n    if weight is not None:\n        loss = ops.mul(loss, weight)\n    return ops.mean(loss)"
}

